import fs from 'node:fs';import path from 'node:path';import {createHash} from 'node:crypto';import {atomicJson} from '../execution/ledger.mjs';import {journalSourceFiles,journalEngineIdentity} from '../live-paper/native-journal-restore.mjs';
const r=path.join(process.env.LOCALAPPDATA,'SigTradingCup/paper-runtime'),source=path.resolve('backend-rust/journal-restore'),sha=b=>createHash('sha256').update(b).digest('hex');
const binary=fs.readFileSync(path.join(source,'target/release/baal-journal-restore.exe')),library=fs.readFileSync(path.join(source,'target/release/libunwind.dll'));
const binding={schemaVersion:1,mode:'canonical_js_journal_restore_v1',binaryHash:sha(binary),engineHash:journalEngineIdentity(source),runtimeLibraryHash:sha(library)};
const buildDir=path.join(r,'journal-native-builds',binding.binaryHash),sourceDir=path.join(r,'journal-native-sources',binding.engineHash);fs.mkdirSync(buildDir,{recursive:true,mode:0o700});fs.mkdirSync(sourceDir,{recursive:true,mode:0o700});
for(const[name,bytes]of [['baal-journal-restore.exe',binary],['libunwind.dll',library]]){const file=path.join(buildDir,name);if(fs.existsSync(file)){if(sha(fs.readFileSync(file))!==sha(bytes))throw Error('Archived journal binary changed');}else fs.writeFileSync(file,bytes,{flag:'wx',mode:0o600});}
const files={};for(const name of journalSourceFiles){const bytes=fs.readFileSync(path.join(source,name)),file=path.join(sourceDir,name);files[name]=sha(bytes);fs.mkdirSync(path.dirname(file),{recursive:true,mode:0o700});if(fs.existsSync(file)){if(sha(fs.readFileSync(file))!==files[name])throw Error('Archived journal source changed');}else fs.writeFileSync(file,bytes,{flag:'wx',mode:0o600});}
atomicJson(path.join(sourceDir,'manifest.json'),{schemaVersion:1,engineHash:binding.engineHash,files});atomicJson('data/journal-native-binding-20261004.json',binding);console.log(JSON.stringify(binding));
